"""Same-origin installation and pairing flow served by the PICO Driver."""

PAGE = r"""<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>连接机器人 · PhanthyMotus</title>
<style>
:root{color-scheme:light;--bg:#F5F0E8;--card:#FDFAF5;--text:#1C1917;--muted:#6D655E;--line:#D8D0C5;--accent:#AD542E;--danger:#B33327}
*{box-sizing:border-box}body{font:16px/1.65 system-ui,sans-serif;max-width:760px;margin:0 auto;padding:40px 24px;background:var(--bg);color:var(--text)}h1{font-size:30px;line-height:1.3;margin:0 0 12px}h2{font-size:20px;line-height:1.4;margin:0 0 16px}p{margin:12px 0}section,details{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:24px;margin:24px 0;box-shadow:0 3px 12px #1C191705}button,a,input{font:inherit;touch-action:manipulation}button,.primary{display:inline-block;min-height:48px;background:var(--accent);color:#fff;border:1px solid transparent;border-radius:6px;padding:11px 18px;text-decoration:none;cursor:pointer;text-align:center}button:hover,.primary:hover{filter:brightness(.94)}button:disabled{background:#E9E3DA;color:#8A8075;cursor:default;filter:none}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #AD542E;outline-offset:3px}small{color:var(--muted);font-size:14px}form{display:flex;flex-wrap:wrap;align-items:center;gap:12px}input{min-height:48px;width:150px;max-width:100%;border:1px solid #b7ad9f;border-radius:10px;padding:10px 14px;background:#fff;color:var(--text)}summary{cursor:pointer;font-weight:600}details button,#logout,button[data-action="reject"]{background:#EDE8DF;color:var(--text);border-color:var(--line);margin:8px 0}button[data-action="revoke_headset"]{color:var(--danger);background:#FDECEA;border-color:#dcb6ad}#status,#pending{background:#EDE8DF;border-radius:10px;padding:14px 16px}#error{color:var(--danger);overflow-wrap:anywhere}#error:not(:empty){border-left:3px solid var(--danger);padding:12px 16px;background:#FDECEA;border-radius:6px}[hidden]{display:none!important}#fingerprint{overflow-wrap:anywhere;font-family:ui-monospace,monospace;letter-spacing:.04em}#package{font-weight:600}@media(max-width:480px){body{padding:24px 16px}h1{font-size:26px}section,details{padding:20px 16px}form label{width:100%}form input{flex:1;min-width:0}#pending button{width:100%}}
</style>
<h1>连接这台机器人</h1><p>请在 PICO 浏览器打开本页。下载安装无需登录，设备管理需要 4 位 PIN。连接后不会自动运动。</p>
<section><h2>1 · 安装 App</h2><a class="primary" href="/onboarding/apk">下载 PICO App</a><p id="package">正在检查安装包…</p><small>下载后确认安装，再返回本页。已经安装可直接进行下一步。</small></section>
<section id="unlock"><h2>2 · 解锁设备管理</h2><p>输入机器人卡片配置的 4 位管理 PIN。</p><form id="login"><label for="pin">管理 PIN</label> <input id="pin" type="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" autocomplete="off" required aria-describedby="login-help"><button id="unlock-button" type="submit">解锁</button></form><small id="login-help">PIN 在卡片齿轮配置中设置，不是头显配对密码。</small></section><div id="management" hidden><button id="logout">退出管理</button><section><h2>2 · 打开并连接</h2><p id="status" role="status">正在读取连接状态…</p><button id="prepare">连接这台机器人</button><a id="connect" class="primary" hidden>打开 App 并连接</a><p><small>如果在电脑上查看，请把当前网址复制到 PICO 浏览器。已配对的 App 再次打开会自动重连。</small></p>
<div id="pending" hidden><p>发现待配对设备，请核对头显中显示的指纹：</p><strong id="fingerprint"></strong><p><button data-action="approve">指纹一致，允许连接</button> <button data-action="reject">不是我的设备</button></p></div></section>

<details><summary>其他连接方式与设备管理</summary><p>App 的“刷新局域网机器人”通过同一局域网的服务广播发现机器人，不扫描 IP。访客 Wi-Fi、组播隔离或跨网段时可能找不到；优先使用上方连接入口。</p><button data-action="open">允许 App 手动发现配对（120 秒）</button><p><small>随后在 App 选择机器人，按提示核对指纹。本页会自动显示配对请求。</small></p><button data-action="revoke_headset">忘记已配对的 PICO</button><p><small>只有更换头显或重新配对时才需要忘记设备。</small></p></details></div><p id="error" role="alert"></p>
<script>
const el=id=>document.getElementById(id);let pending=null,busy=false,unlocked=false,epoch=0;
function lock(){epoch++;unlocked=false;pending=null;el("management").hidden=true;el("unlock").hidden=false;el("connect").hidden=true;el("connect").removeAttribute("href");el("pending").hidden=true;el("fingerprint").textContent="";}
const errors={management_pin_required:'请输入管理 PIN 解锁。',management_session_expired:'管理会话已过期，请重新输入 PIN。',management_pin_invalid:'PIN 不正确，请重试。',management_rate_limited:'尝试过于频繁，请稍后重试。',management_pin_not_configured:'尚未设置管理 PIN，请在卡片齿轮配置中设置 4 位 PIN。',pairing_window_closed:'配对窗口已关闭，请重新允许手动配对。',revoke_existing_headset_first:'已有配对设备；请直接打开已配对的 App。更换头显时，在设备管理中忘记旧设备。',invitation_expired:'连接邀请已过期，请重新点击连接。'};
async function call(action,values={}){const r=await fetch('/manage/'+action,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});const v=await r.json();if(!r.ok){if(r.status===401||v.error==='management_pin_not_configured')lock();throw Error(errors[v.error]||v.error||'请求失败，请重试');}return v;}
function show(v){if(v.pairing){pending=v.pairing.pending;if(!v.pairing.invitation)el('connect').hidden=true;el('pending').hidden=!pending;el('fingerprint').textContent=pending?pending.fingerprint:'';}if(v.capture){el('status').textContent=v.capture.connected?'PICO 已连接。G1：松开双握把，确认双臂自然下垂，长按 X+A 一秒建立基准；松键后重新按下双握把接通，松开任一握把暂停。结束本轮：松开双握把，长按 Y+B 一秒；请求发送成功后现场确认复位。保留智能控制，下次遥操再建立基准。':v.capture.paired_devices?'已配对，请打开 PICO App 自动重连。':'尚未配对，点击下方按钮，App 将自动填好这台机器人的地址。';el('prepare').hidden=!!v.capture.paired_devices||!el('connect').hidden;if(v.capture.paired_devices)el('connect').hidden=true;}}
async function refresh(){if(busy)return;const generation=epoch;try{const v=await call('status');if(generation!==epoch)return;unlocked=true;el('management').hidden=false;el('unlock').hidden=true;el('error').textContent='';show(v);}catch(e){el('error').textContent='暂时无法读取状态：'+e.message;}}
el('prepare').onclick=async()=>{busy=true;el('prepare').disabled=true;el('error').textContent='';try{const v=await call('invite');el('connect').href=v.deep_link;el('connect').hidden=false;el('prepare').hidden=true;el('status').textContent='地址已准备好，点击“打开 App 并连接”，无需手动填写。';}catch(e){el('error').textContent=e.message;}finally{busy=false;el('prepare').disabled=false;}};
for(const b of document.querySelectorAll('[data-action]'))b.onclick=async()=>{busy=true;b.disabled=true;el('error').textContent='';try{const a=b.dataset.action;let data={};if(a==='approve'||a==='reject'){if(!pending)throw Error('当前没有待配对设备');data={request_id:pending.request_id,fingerprint:pending.fingerprint};}if(a==='revoke_headset'&&!confirm('忘记设备后需要重新连接，继续？'))return;show(await call(a,data));if(a==='revoke_headset')el('connect').hidden=true;}catch(e){el('error').textContent=e.message;}finally{busy=false;b.disabled=false;await refresh();}};
el('login').onsubmit=async event=>{event.preventDefault();const pin=el('pin').value;el('pin').value='';if(!/^[0-9]{4}$/.test(pin)){el('error').textContent='请输入 4 位数字 PIN。';return;}busy=true;el('unlock-button').disabled=true;el('error').textContent='';try{await call('login',{pin});}catch(e){el('error').textContent=e.message;return;}finally{busy=false;el('unlock-button').disabled=false;}await refresh();};
el('logout').onclick=async()=>{busy=true;try{await call('logout');lock();el('error').textContent='已退出设备管理。';}catch(e){el('error').textContent=e.message;}finally{busy=false;}};
refresh();setInterval(()=>{if(unlocked)refresh();},2000);
fetch('/onboarding/package').then(r=>r.json()).then(v=>{el('package').textContent=v.available?'版本 '+v.version:'安装包尚未就绪，请联系部署人员。';}).catch(()=>{el('package').textContent='暂时无法读取安装包信息，请刷新页面。';});
</script></html>"""
